<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Card</title>
  <style>
    /* 页面整体居中：flex 水平 + 垂直居中，最小高度占满视口 */
    html, body {
      height: 100%;
      margin: 0;
    }
    body {
      display: flex;
      justify-content: center;   /* 水平居中 */
      align-items: center;       /* 垂直居中 */
      min-height: 100vh;
    }
    /* 卡片：蓝色背景 + 明显圆角 */
    .card {
      background-color: #1976d2;             /* 蓝色背景 */
      border-radius: 16px;                   /* 明显圆角 */
      color: #ffffff;
      width: 320px;
      padding: 40px 32px;
      box-sizing: border-box;
      text-align: center;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
    }
    .card h1 {
      margin: 0 0 8px;
      font-size: 22px;
    }
    .card p {
      margin: 0;
      font-size: 14px;
      opacity: 0.9;
    }
  </style>
</head>
<body>
  <div class="card">
    <h1>卡片标题</h1>
    <p>这是卡片内的简单占位文字。</p>
  </div>
</body>
</html>
"}

